const review = $input.first().json;
const stars = review.starRating;
const comment = (review.comment || "").toLowerCase();

let action = "notify_admin";
let reply = "";
let priority = "normal";

if (stars >= 4) {
  action = "auto_reply";
  reply = "\u00a1Gracias por tu rese\u00f1a! Nos alegra que hayas disfrutado de Golden Harvest. Tu opini\u00f3n nos motiva a seguir mejorando.";
} else {
  if (comment.includes("demora") || comment.includes("roto") || comment.includes("p\u00e9simo") || comment.includes("horrible")) {
    action = "urgent_admin";
    priority = "urgent";
  }
}

return [{
  json: {
    ...review,
    action,
    priority,
    suggested_reply: reply,
    reviewer_name: review.reviewer?.displayName || review.reviewerDisplayName || "Cliente",
    stars_numeric: typeof stars === 'number' ? stars : (["ONE", "TWO", "THREE", "FOUR", "FIVE"].indexOf(stars) + 1)
  }
}];

const reviews = $input.first().json.result?.reviews ?? [];
return reviews.map(r => ({
  json: {
    reviewId: `places_${r.time}`,
    reviewer: { displayName: r.author_name },
    starRating: ['ONE','TWO','THREE','FOUR','FIVE'][r.rating - 1],
    comment: r.text,
    source: 'places_api'
  }
}));

// [TESIS] Emit each review as a separate item — no external API needed
return [
  { json: { reviewId: "rev001", starRating: 5, comment: "Excelentes productos, el pesto de oliva es increíble. Muy buena atención.", reviewerDisplayName: "María González" } },
  { json: { reviewId: "rev002", starRating: 2, comment: "La entrega demoró más de lo esperado y el frasco llegó con la tapa floja.", reviewerDisplayName: "Carlos Pérez" } },
  { json: { reviewId: "rev003", starRating: 4, comment: "Muy buenas mermeladas artesanales. El chutney de ciruela es delicioso.", reviewerDisplayName: "Ana Rodríguez" } },
  { json: { reviewId: "rev004", starRating: 1, comment: "Pésimo servicio, nunca respondieron mi reclamo y el producto llegó roto.", reviewerDisplayName: "Juan Martínez" } },
  { json: { reviewId: "rev005", starRating: 5, comment: "Los mejores productos artesanales de la región. El aceite de oliva es excepcional.", reviewerDisplayName: "Laura Sánchez" } }
];

// [TESIS] Process all reviews at once — classify + generate reply/escalation
const items = $input.all();
const results = [];

for (const item of items) {
  const r = item.json;
  const stars = r.starRating;
  const comment = (r.comment || '').toLowerCase();
  const name = r.reviewerDisplayName || 'Cliente';

  let action, priority, reply, escalation;

  if (stars >= 4) {
    action = 'auto_reply';
    priority = 'normal';
    reply = `¡Muchas gracias ${name}! Nos alegra mucho que disfrutes de nuestros productos Golden Harvest. Tu opinión es muy valiosa para nosotros.`;
    escalation = null;
  } else {
    action = (comment.includes('demora') || comment.includes('roto') || comment.includes('pésimo') || comment.includes('horrible'))
      ? 'urgent_admin' : 'notify_admin';
    priority = action === 'urgent_admin' ? 'urgent' : 'normal';
    reply = null;
    escalation = `Contactar a ${name} para resolver su experiencia negativa y ofrecer compensación si corresponde.`;
  }

  results.push({
    reviewId: r.reviewId,
    reviewer: name,
    stars,
    comment: r.comment,
    action,
    priority,
    tesis_reply: reply,
    escalation_suggestion: escalation
  });
}

return [{ json: { all_reviews: results } }];

// [TESIS] Build HTML email with all review results
const data = $input.first().json;
const reviews = data.all_reviews;

const positive = reviews.filter(r => r.action === 'auto_reply');
const negative = reviews.filter(r => r.action !== 'auto_reply');
const urgent = reviews.filter(r => r.priority === 'urgent');

const starsBar = (n) => '⭐'.repeat(n) + '☆'.repeat(5 - n);

const positiveRows = positive.map(r => `
  <tr style="background:#f0fdf4">
    <td style="padding:8px">${starsBar(r.stars)} (${r.stars})</td>
    <td style="padding:8px"><b>${r.reviewer}</b><br><small>${r.comment}</small></td>
    <td style="padding:8px;color:#16a34a"><i>${r.tesis_reply}</i></td>
  </tr>`).join('');

const negativeRows = negative.map(r => `
  <tr style="background:${r.priority==='urgent'?'#fff1f2':'#fffbeb'}">
    <td style="padding:8px">${starsBar(r.stars)} (${r.stars})</td>
    <td style="padding:8px"><b>${r.reviewer}</b><br><small>${r.comment}</small></td>
    <td style="padding:8px;color:#dc2626">${r.priority==='urgent'?'🚨 URGENTE':'⚠️ Atención'}<br><small>${r.escalation_suggestion}</small></td>
  </tr>`).join('');

const html = `
<html><body style="font-family:Arial,sans-serif;max-width:700px;margin:auto">
  <h2 style="color:#15803d">🌿 Golden Harvest S.A. — Reporte de Reseñas Google Maps</h2>
  <p style="color:#666">Procesado: ${new Date().toLocaleString('es-AR')}</p>

  <table style="width:100%;border-collapse:collapse;margin-bottom:16px">
    <tr>
      <td style="background:#15803d;color:white;padding:12px;border-radius:6px;text-align:center"><b>${reviews.length}</b><br>Total</td>
      <td style="width:12px"></td>
      <td style="background:#16a34a;color:white;padding:12px;border-radius:6px;text-align:center"><b>${positive.length}</b><br>Positivas</td>
      <td style="width:12px"></td>
      <td style="background:#dc2626;color:white;padding:12px;border-radius:6px;text-align:center"><b>${negative.length}</b><br>Negativas</td>
      <td style="width:12px"></td>
      <td style="background:#7f1d1d;color:white;padding:12px;border-radius:6px;text-align:center"><b>${urgent.length}</b><br>Urgentes</td>
    </tr>
  </table>

  ${positive.length ? `
  <h3 style="color:#16a34a">✅ Reseñas Positivas — Respuesta Automática Generada</h3>
  <table style="width:100%;border-collapse:collapse;font-size:13px">
    <tr style="background:#dcfce7"><th style="padding:8px;text-align:left">Estrellas</th><th style="padding:8px;text-align:left">Reseña</th><th style="padding:8px;text-align:left">Respuesta Sugerida</th></tr>
    ${positiveRows}
  </table>` : ''}

  ${negative.length ? `
  <h3 style="color:#dc2626">⚠️ Reseñas Negativas — Requieren Atención</h3>
  <table style="width:100%;border-collapse:collapse;font-size:13px">
    <tr style="background:#fee2e2"><th style="padding:8px;text-align:left">Estrellas</th><th style="padding:8px;text-align:left">Reseña</th><th style="padding:8px;text-align:left">Acción Sugerida</th></tr>
    ${negativeRows}
  </table>` : ''}

  <p style="color:#999;font-size:11px;margin-top:24px">Workflow 03 — Google Maps Review Management | Golden Harvest S.A. | Modo TESIS (simulado)</p>
</body></html>`;

return [{ json: { subject: `[Golden Harvest] Reseñas Google Maps — ${positive.length} positivas, ${negative.length} negativas${urgent.length ? ', ' + urgent.length + ' URGENTES' : ''}`, html_body: html, summary: { total: reviews.length, positivas: positive.length, negativas: negative.length, urgentes: urgent.length } } }];
